with payload as (
 select value as item from jsonb_array_elements($DADYOOM$[{"order":1,"title":"القراءة: من القرآن الكريم (أقرأ وأتدبر)","lessonType":"reading","content":"القراءة: من القرآن الكريم (أقرأ وأتدبر)\n\nما الذي سأتعلمه؟\n• يطبق خطوات القراءة المتأنية والتدبر في نص قرآني موثق.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nعندما أقرأ القرآن الكريم أستخدم نصًا صحيحًا موثقًا من المصحف، وأنتبه إلى ضبط الحركات ومواضع الوقف. لا أصوغ آيات جديدة ولا أعتمد عبارة من الذاكرة إذا شككت في دقتها. أبدأ بتحديد معنى مفردة من تفسير معتمد وأستخرج قيمة سلوكية مما قرأت.\n\nمثال محلول أو نموذج\nخطوات التعلم: تحقق من اسم السورة والآية، اقرأ مع التشكيل، اسأل عن معنى مفردة موثقة، ثم صغ درسًا أخلاقيًا بأسلوبك.\n\nأطبق بنفسي\nاذكر خطوتين للتحقق من النص القرآني قبل تلاوته. لماذا نتحقق من الحركات؟ ماذا تفعل إذا لم تتأكد من معنى كلمة؟\n\nمفتاح الإجابة النموذجي\nنقارن النص بمصحف موثق ونثبت السورة والآية؛ للحفاظ على ضبط التلاوة؛ نرجع إلى تفسير موثوق أو نسأل المعلم.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يطبق خطوات القراءة المتأنية والتدبر في نص قرآني موثق.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"تدبر","meaning":"تأمل المعنى وفهمه"},{"word":"تلاوة","meaning":"قراءة القرآن قراءة مضبوطة"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":2,"title":"التراكيب اللغوية: استعمال فعل الأمر","lessonType":"grammar","content":"التراكيب اللغوية: استعمال فعل الأمر\n\nما الذي سأتعلمه؟\n• يكون جملة قصيرة تبدأ بفعل أمر مناسب.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nنستعمل فعل الأمر لطلب عمل من المخاطب بصورة واضحة. أمثلة: «اقرأ»، «اكتب»، «استمع». ويمكن إضافة كلمة لبيان المطلوب: «اقرأ الرسالة»، «اكتب الاسم». في المخاطبة المهذبة نستخدم من فضلك ونبرة لطيفة.\n\nمثال محلول أو نموذج\nاقرأ الإعلان. افتح الكتاب. اكتب اسمك. استمع جيدًا.\n\nأطبق بنفسي\nحوّل «أنت تكتب الاسم» إلى طلب أمر. اختر فعل الأمر بين «كتب»، «يكتب»، «اكتب». أنشئ طلبًا مهذبًا موجّهًا لزميلك.\n\nمفتاح الإجابة النموذجي\n«اكتب الاسم»؛ «اكتب»؛ مثال «اقرأ التعليمات من فضلك».\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يكون جملة قصيرة تبدأ بفعل أمر مناسب.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"أمر","meaning":"طلب أداء فعل"},{"word":"مخاطب","meaning":"الشخص الذي نوجه إليه الكلام"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":3,"title":"الإملاء والخط: مراجعة عامة لما سبق دراسته","lessonType":"spelling","content":"الإملاء والخط: مراجعة عامة لما سبق دراسته\n\nما الذي سأتعلمه؟\n• يراجع كتابة الحروف والمدود وعلامات التنقيط.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nأراجع مواضع النقاط في حروف مثل ب وت وث ون، ثم أفرق بين الحركات القصيرة وحروف المد. أكتب الكلمات من اليمين إلى اليسار بوضوح، وأتأكد من عدد النقاط قبل إنهاء السطر.\n\nمثال محلول أو نموذج\nب نقطة أسفل؛ ت نقطتان أعلى؛ ث ثلاث نقاط أعلى؛ ن نقطة أعلى. بَ أقصر صوتًا من با.\n\nأطبق بنفسي\nاكتب كلمة «بيت» مع النقط. كم نقطة في الثاء؟ حدد المد في «نور». ما الفرق بين «بَ» و«با» من حيث طول الصوت؟\n\nمفتاح الإجابة النموذجي\nبيت بنقطتي الياء والتاء؛ ثلاث نقاط؛ الواو في «نور»؛ «با» صوتها أطول.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يراجع كتابة الحروف والمدود وعلامات التنقيط.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"تنقيط","meaning":"وضع نقاط الحروف"},{"word":"مد","meaning":"إطالة الصوت بحرف مد مناسب"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":4,"title":"القراءة: الصندوق الخيري","lessonType":"reading","content":"القراءة: الصندوق الخيري\n\nما الذي سأتعلمه؟\n• يقرأ موقفًا عن العمل الخيري ويحدد أثر المساهمة.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nنص تدريبي أصلي: «اجتمع سكان الحي لدعم أسرة محتاجة. وضع كل متبرع مبلغًا في صندوق موثق لدى الجمعية. اشترت الجمعية حاجات أساسية للأسرة، وأعلنت تقريرًا واضحًا عن المصروفات». هذا النص من ضاديوم، وليس مقتبسًا من «الصندوق الخيري» الرسمي.\n\nمثال محلول أو نموذج\nتعاون السكان، وراقبت الجمعية جمع التبرعات وإنفاقها.\n\nأطبق بنفسي\nلمن خُصصت المساعدة؟ لماذا يفيد نشر تقرير عن أوجه الصرف؟ استخرج كلمة تدل على المشاركة.\n\nمفتاح الإجابة النموذجي\nلأسرة محتاجة؛ للشفافية وتعزيز الثقة؛ «متبرع» أو «تعاون».\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يقرأ موقفًا عن العمل الخيري ويحدد أثر المساهمة.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"خيري","meaning":"يهدف إلى نفع الناس دون مقابل"},{"word":"شفافية","meaning":"وضوح في الإجراءات والمعلومات"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":5,"title":"التراكيب اللغوية: استعمال الفعل الناسخ (كان)؛ أقسام الكلام (الاسم، الفعل، الحرف)؛ استعمال حروف الجر","lessonType":"grammar","content":"التراكيب اللغوية: استعمال الفعل الناسخ (كان)؛ أقسام الكلام (الاسم، الفعل، الحرف)؛ استعمال حروف الجر\n\nما الذي سأتعلمه؟\n• يميز الاسم والفعل والحرف ويوظف كان وحرف الجر.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nالاسم يدل على شخص أو شيء، والفعل على حدث، والحرف يربط المعاني. «كان» فعل ناسخ يدخل على الجملة الاسمية؛ نقول «الجو جميل» ثم «كان الجو جميلًا». ألاحظ أثره في خبر الجملة دون تعقيد؛ وحرف الجر يدخل قبل الاسم مثل «في البيت».\n\nمثال محلول أو نموذج\nالولد مجتهد ← كان الولد مجتهدًا. في جملة «جلس جاسم في البيت»: جلس فعل، جاسم اسم، في حرف.\n\nأطبق بنفسي\nحدد الفعل والاسم والحرف في «ذهب علي إلى السوق». أكمل «كان الجو ...» بصفة مناسبة مع ضبط آخرها. اذكر حرف جر.\n\nمفتاح الإجابة النموذجي\nذهب فعل، علي والسوق اسمان، إلى حرف؛ «كان الجو لطيفًا»؛ مثال «في».\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يميز الاسم والفعل والحرف ويوظف كان وحرف الجر.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"ناسخ","meaning":"فعل يدخل على الجملة الاسمية ويغير إعراب الخبر"},{"word":"حرف جر","meaning":"حرف يربط الاسم بما قبله"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":6,"title":"الإملاء والخط: كتابة آية بخط النسخ","lessonType":"spelling","content":"الإملاء والخط: كتابة آية بخط النسخ\n\nما الذي سأتعلمه؟\n• ينسخ نصًا قرآنيًا موثقًا بخط النسخ مع حفظ الضبط.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nأستخدم آية يحددها المعلم من مصحف معتمد، ولا أكتب كلمات قرآنية من الذاكرة دون مراجعة. ألاحظ رسم الحروف واتصالها والتشكيل كما هو في المصدر، وأراعي خصوصية الرسم العثماني عند النسخ. يمكن التدرب أولًا بجملة عربية عادية قبل كتابة الآية.\n\nمثال محلول أو نموذج\nتدريب على الخط غير قرآني: «العلم نور». أكتبها على السطر بتباعد مناسب بين الكلمات.\n\nأطبق بنفسي\nما مصدر الآية الصحيح قبل نسخها؟ ما الذي يجب مراجعته بعد الكتابة؟ انسخ الجملة التدريبية «العلم نور».\n\nمفتاح الإجابة النموذجي\nمصحف موثق يحدده المعلم؛ الحروف والنقاط والتشكيل ومطابقة النص؛ الجملة المطلوبة مكتوبة بخط واضح.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["ينسخ نصًا قرآنيًا موثقًا بخط النسخ مع حفظ الضبط.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"النسخ","meaning":"نوع من الخط العربي الواضح"},{"word":"ضبط","meaning":"علامات الحركات والشكل"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":7,"title":"التعبير: تكوين جمل قصيرة للتعبير عن فكرة أو موقف؛ كتابة فقرة مترابطة (في حدود سبع جمل)","lessonType":"writing","content":"التعبير: تكوين جمل قصيرة للتعبير عن فكرة أو موقف؛ كتابة فقرة مترابطة (في حدود سبع جمل)\n\nما الذي سأتعلمه؟\n• ينظم سبع جمل متتابعة حول فكرة واحدة.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nالفقرة الجيدة تبدأ بجملة تحدد الموضوع، ثم جمل توضح التفاصيل، وتنتهي بخلاصة. أختار موضوعًا عمليًا مثل التعاون في الحي. أكتب سبع جمل قصيرة مترابطة وأستخدم ألفاظًا بسيطة: أولًا، ثم، بعد ذلك، أخيرًا.\n\nمثال محلول أو نموذج\nجملة افتتاحية: «التعاون يجعل الحي أفضل». تفصيل: «يجتمع الجيران لتنظيف الشارع». خاتمة: «يسعد الجميع عندما ينجح العمل».\n\nأطبق بنفسي\nاكتب سبع جمل عن خدمة الحي. هل تتحدث الجملة الأخيرة عن الفكرة نفسها؟ ضع نقطة في نهاية كل جملة.\n\nمفتاح الإجابة النموذجي\nتقبل سبع جمل مترابطة تتضمن بداية وتفاصيل وخاتمة، ويُراجع ترتيبها وعلامات نهايتها.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["ينظم سبع جمل متتابعة حول فكرة واحدة.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"فقرة","meaning":"جمل مترابطة تدور حول فكرة واحدة"},{"word":"خاتمة","meaning":"الجملة التي تُنهي الفكرة"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":8,"title":"القراءة: جمعية مدينتنا التعاونية","lessonType":"reading","content":"القراءة: جمعية مدينتنا التعاونية\n\nما الذي سأتعلمه؟\n• يحدد دور الجمعية التعاونية من نص تدريبي ويفسر فائدتها.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nنص تدريبي من ضاديوم: «افتتحت الجمعية التعاونية متجرًا يخدم الحي. وفرت سلعًا أساسية وأسعارًا واضحة، ونظمت حملة لتقليل هدر الطعام. اشترى خالد احتياجات أسرته، واحتفظ بالفاتورة». هذا النص لدعم القراءة وليس نص «جمعية مدينتنا التعاونية» الأصلي.\n\nمثال محلول أو نموذج\nتوفر الجمعية منتجات يحتاجها السكان، وتشرح أسعارها بطريقة واضحة.\n\nأطبق بنفسي\nماذا وفرت الجمعية؟ ما فائدة الاحتفاظ بالفاتورة؟ اذكر إجراءً يقلل هدر الطعام.\n\nمفتاح الإجابة النموذجي\nالسلع الأساسية؛ التحقق من المشتريات والحقوق؛ التخطيط للشراء أو حفظ الطعام جيدًا.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يحدد دور الجمعية التعاونية من نص تدريبي ويفسر فائدتها.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"تعاونية","meaning":"منشأة يشارك فيها أعضاء لخدمة احتياجات مشتركة"},{"word":"فاتورة","meaning":"وثيقة توضح قيمة المشتريات"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":9,"title":"التراكيب اللغوية: استعمال أداة الشرط «كلما» في تكوين جمل","lessonType":"grammar","content":"التراكيب اللغوية: استعمال أداة الشرط «كلما» في تكوين جمل\n\nما الذي سأتعلمه؟\n• يوظف كلما للتعبير عن تكرار ارتباط حدثين.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nتربط «كلما» حدثًا متكررًا بنتيجة تتكرر معه. نقول: «كلما قرأت أكثر زادت حصيلتي اللغوية». نلاحظ أن الأمر ليس سؤالًا بل ربط بين تكرارين. نستعمل جملة واقعية واضحة.\n\nمثال محلول أو نموذج\nكلما تدربت تحسّن خطي. كلما حضر الناس مبكرًا بدأ الاجتماع في موعده.\n\nأطبق بنفسي\nأكمل «كلما تعاونّا ...». هل «كلما» تدل على حدث متكرر أم وقت ثابت مرة واحدة؟ كوّن مثالًا متعلقًا بالقراءة.\n\nمفتاح الإجابة النموذجي\nمثال «كلما تعاونّا أنجزنا العمل أسرع»؛ التكرار؛ «كلما قرأت تعلمت كلمات جديدة».\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يوظف كلما للتعبير عن تكرار ارتباط حدثين.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"كلما","meaning":"أداة تربط تكرار حدث بتكرار نتيجته"},{"word":"نتيجة","meaning":"ما يحدث إثر فعل"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":10,"title":"الإملاء والخط: التاء المفتوحة والتاء المربوطة","lessonType":"spelling","content":"الإملاء والخط: التاء المفتوحة والتاء المربوطة\n\nما الذي سأتعلمه؟\n• يميز التاء المفتوحة من التاء المربوطة عند الكتابة.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nتكتب التاء المفتوحة «ت» وتظهر في كلمات مثل «بيت» و«بنت»، ويمكن نطقها تاء عند الوقف. وتكتب التاء المربوطة «ة» في كلمات مثل «مدرسة» و«حديقة» وتنطق هاء غالبًا عند الوقف وتاء عند الوصل بحسب السياق.\n\nمثال محلول أو نموذج\nبيت — بنت — كتبت: تاء مفتوحة. مدرسة — شجرة — حديقة: تاء مربوطة.\n\nأطبق بنفسي\nاختر الرسم الصحيح: «مدرسـة» أم «مدرست» لاسم مكان الدراسة؟ ما نوع التاء في «بنت»؟ أكمل «حديقـ...» بالحرف المناسب.\n\nمفتاح الإجابة النموذجي\nمدرسة؛ مفتوحة؛ «حديقة» تاء مربوطة.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يميز التاء المفتوحة من التاء المربوطة عند الكتابة.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"تاء مفتوحة","meaning":"تكتب ت"},{"word":"تاء مربوطة","meaning":"تكتب ة في آخر كثير من الأسماء"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":11,"title":"التعبير: تكوين جمل قصيرة للتعبير عن فكرة أو موقف؛ كتابة فقرة مترابطة للتعبير عن مقترح","lessonType":"writing","content":"التعبير: تكوين جمل قصيرة للتعبير عن فكرة أو موقف؛ كتابة فقرة مترابطة للتعبير عن مقترح\n\nما الذي سأتعلمه؟\n• يكتب مقترحًا واضحًا في فقرة قصيرة.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nالمقترح يعرض مشكلة أو فرصة وحلًا مناسبًا. أكتب: ما المشكلة؟ ماذا أقترح؟ من ينفذ؟ وما النتيجة المتوقعة؟ أستخدم جملًا مهذبة محددة بدل عبارات عامة. يمكن أن يكون المقترح حول مكتبة الحي أو تنظيم النظافة.\n\nمثال محلول أو نموذج\n«أقترح وضع صناديق فرز للنفايات في الحديقة. يشارك المتطوعون في تعريف الزوار بطريقة الاستخدام. بذلك نحافظ على نظافة المكان».\n\nأطبق بنفسي\nاكتب مقترحًا من أربع إلى ست جمل لتحسين خدمة عامة. حدد فيه الحل والشخص المسؤول وفائدة التنفيذ.\n\nمفتاح الإجابة النموذجي\nتقبل فقرة مترابطة تحدد مقترحًا عمليًا وطريقة تنفيذه وفائدته، مع سلامة علامات الترقيم.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يكتب مقترحًا واضحًا في فقرة قصيرة.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"مقترح","meaning":"فكرة مقدمة للتحسين أو الحل"},{"word":"تنفيذ","meaning":"تحويل الفكرة إلى عمل"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":12,"title":"القراءة: أوقات الفراغ","lessonType":"reading","content":"القراءة: أوقات الفراغ\n\nما الذي سأتعلمه؟\n• يقرأ نصًا قصيرًا ويستنتج قيمة تنظيم أوقات الفراغ.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nنص ضاديوم: «أنهى سالم عمله مبكرًا. خصص نصف ساعة للقراءة ووقتًا للمشي مع أسرته، ثم زار صديقه. شعر بالرضا لأنه نظم يومه». النص أصلي مساعد على مهارة الفهم، ولا يمثل نص «أوقات الفراغ» من الكتاب.\n\nمثال محلول أو نموذج\nيمكن استثمار وقت الفراغ في القراءة أو الرياضة أو صلة الرحم.\n\nأطبق بنفسي\nاذكر نشاطين مارسهما سالم. لماذا شعر بالرضا؟ اقترح نشاطًا يناسب وقتك وعلّل اختيارك.\n\nمفتاح الإجابة النموذجي\nالقراءة والمشي والزيارة؛ لأنه نظم وقته؛ تقبل إجابة مبررة مناسبة.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يقرأ نصًا قصيرًا ويستنتج قيمة تنظيم أوقات الفراغ.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"فراغ","meaning":"وقت خارج الالتزامات الأساسية"},{"word":"تنظيم","meaning":"ترتيب الأنشطة بحسب الحاجة"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":13,"title":"التراكيب اللغوية: استعمال السين وسوف مع الفعل المضارع؛ استعمال أداة الجزم «لم» وأداة النصب «لن»؛ استعمال أدوات الاستفهام المختلفة","lessonType":"grammar","content":"التراكيب اللغوية: استعمال السين وسوف مع الفعل المضارع؛ استعمال أداة الجزم «لم» وأداة النصب «لن»؛ استعمال أدوات الاستفهام المختلفة\n\nما الذي سأتعلمه؟\n• يميز السين وسوف ولم ولن مع الفعل المضارع ويطرح سؤالًا صحيحًا.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nالسين وسوف تدلان على الاستقبال: «سأزور» و«سوف أزور». «لم» لنفي وقوع فعل في الماضي وتجزم المضارع: «لم يذهبْ». «لن» لنفي وقوعه مستقبلًا وتنصب المضارع: «لن يذهبَ». نختار الأداة بحسب المعنى ثم نضع أداة الاستفهام المناسبة للسؤال.\n\nمثال محلول أو نموذج\nسأقرأ غدًا. سوف نبدأ بعد قليل. لم أخرج أمس. لن أتأخر غدًا.\n\nأطبق بنفسي\nأكمل «... أزور المكتبة غدًا» بوسيلة استقبال. اختر «لم» أو «لن» في «... أتغيب أمس». أنشئ سؤالًا عن الموعد.\n\nمفتاح الإجابة النموذجي\n«سوف أزور» أو «سأزور»؛ «لم أتغيبْ أمس»؛ مثال «متى تبدأ الزيارة؟».\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يميز السين وسوف ولم ولن مع الفعل المضارع ويطرح سؤالًا صحيحًا.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"الاستقبال","meaning":"زمن مستقبل لم يحدث بعد"},{"word":"جزم","meaning":"حالة نحوية تظهر بعد أدوات مثل لم"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":14,"title":"الإملاء والخط: علامات الترقيم","lessonType":"spelling","content":"الإملاء والخط: علامات الترقيم\n\nما الذي سأتعلمه؟\n• يوظف النقطة والفاصلة وعلامتي الاستفهام والتعجب.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nأستخدم النقطة عند انتهاء جملة خبرية، والفاصلة عند الفصل بين أجزاء متقاربة، وعلامة الاستفهام «؟» بعد السؤال، وعلامة التعجب «!» للتعجب أو الانفعال. العلامات تساعد القارئ على فهم المعنى وطريقة الوقف.\n\nمثال محلول أو نموذج\nذهبت إلى السوق. اشتريت خبزًا، وحليبًا، وفاكهة. أين الفاتورة؟ ما أجمل المكان!\n\nأطبق بنفسي\nضع علامة مناسبة: «أين المكتبة ...» و«وصلت الحافلة ...». أعد كتابة «اشتريت خبزا وحليبا» بفاصلة مناسبة.\n\nمفتاح الإجابة النموذجي\nأين المكتبة؟ وصلت الحافلة. اشتريت خبزًا، وحليبًا.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يوظف النقطة والفاصلة وعلامتي الاستفهام والتعجب.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"ترقيم","meaning":"وضع علامات لتنظيم المعنى"},{"word":"فاصلة","meaning":"علامة وقف قصير: ،"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":15,"title":"التعبير: كتابة فقرة مترابطة بتوظيف علامات الترقيم المناسبة","lessonType":"writing","content":"التعبير: كتابة فقرة مترابطة بتوظيف علامات الترقيم المناسبة\n\nما الذي سأتعلمه؟\n• ينتج فقرة مترابطة مضبوطة بعلامات الترقيم.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nأبدأ بجملة رئيسة وأشرحها بجمل قصيرة متصلة، ثم أختم الفقرة. أختار علامات الترقيم بحسب وظيفة كل جملة: النقطة عند الانتهاء، والفاصلة في التعداد، والسؤال يحتاج علامة الاستفهام. أراجع الترتيب قبل تسليم النص.\n\nمثال محلول أو نموذج\n«أحب القراءة. أقرأ الأخبار، والقصص، والنصوص النافعة. لماذا أقرأ كل يوم؟ لأن القراءة تساعدني على الفهم».\n\nأطبق بنفسي\nاكتب خمس جمل عن زيارة مكان عام؛ ضع نقطة في نهاية الخبر، وفاصلة عند التعداد، وعلامة استفهام إذا طرحت سؤالًا.\n\nمفتاح الإجابة النموذجي\nتقبل فقرة أصلية واضحة مترابطة من خمس جمل مع توظيف صحيح لعلامات الترقيم بحسب المعنى.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["ينتج فقرة مترابطة مضبوطة بعلامات الترقيم.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"ترابط","meaning":"اتصال الجمل بموضوع واحد"},{"word":"مسودة","meaning":"نص أولي يُراجع قبل اعتماده"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":16,"title":"القراءة: البحرين ترحب بكم","lessonType":"reading","content":"القراءة: البحرين ترحب بكم\n\nما الذي سأتعلمه؟\n• يستخرج معلومة عن استقبال الزوار من نص داعم.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nنص ضاديوم: «استقبل مركز المعلومات زوار البحرين. قدم لهم خريطة للمعالم وأوقات الزيارة، وشرح وسائل المواصلات. شكر الزوار الموظف على حسن الاستقبال». هذا النص من تأليف ضاديوم لدعم المهارة ولا يطابق نص «البحرين ترحب بكم» الرسمي.\n\nمثال محلول أو نموذج\nمركز المعلومات يساعد الزائر على الوصول إلى الأماكن المناسبة ومعرفة مواعيدها.\n\nأطبق بنفسي\nماذا قدم المركز للزوار؟ ما المعلومات التي يحتاجها الزائر قبل انتقاله؟ اذكر سلوكًا يدل على حسن الترحيب.\n\nمفتاح الإجابة النموذجي\nخريطة ومعلومات؛ المواصلات والمواعيد؛ حسن الاستقبال وتقديم المساعدة.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يستخرج معلومة عن استقبال الزوار من نص داعم.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"معالم","meaning":"أماكن بارزة يقصدها الناس"},{"word":"مواصلات","meaning":"وسائل الانتقال بين الأماكن"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":17,"title":"التراكيب اللغوية: الجملة الفعلية والجملة الاسمية","lessonType":"grammar","content":"التراكيب اللغوية: الجملة الفعلية والجملة الاسمية\n\nما الذي سأتعلمه؟\n• يفرق بين الجملة الاسمية والفعلية ويؤلف مثالًا لكل منهما.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nالجملة الاسمية تبدأ باسم في أصل تركيبها: «البحرين جميلة». والجملة الفعلية تبدأ بفعل: «زارت الأسرة المتحف». أقرأ بداية الجملة لتحديد نوعها، ثم أتأكد من اكتمال المعنى.\n\nمثال محلول أو نموذج\nاسمية: «العمل مفيد». فعلية: «انتهى العمل». اسمية: «الحديقة واسعة».\n\nأطبق بنفسي\nصنف: «سافر أحمد» و«الميناء مزدحم». اكتب جملة اسمية عن الحي وجملة فعلية عن زيارة.\n\nمفتاح الإجابة النموذجي\n«سافر أحمد» فعلية، و«الميناء مزدحم» اسمية؛ تقبل أمثلة صحيحة مكتملة.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يفرق بين الجملة الاسمية والفعلية ويؤلف مثالًا لكل منهما.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"اسمية","meaning":"جملة تبدأ باسم في أصل تركيبها"},{"word":"فعلية","meaning":"جملة تبدأ بفعل"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":18,"title":"الإملاء والخط: كتابة جملة بخط النسخ","lessonType":"spelling","content":"الإملاء والخط: كتابة جملة بخط النسخ\n\nما الذي سأتعلمه؟\n• ينسخ جملة واضحة بخط النسخ محافظًا على مواقع الحروف.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nأراعي عند الكتابة بخط النسخ بداية السطر واتجاه الكتابة من اليمين، وأحافظ على الفراغ المناسب بين الكلمات. أنتبه إلى ارتفاع الحروف ونقاطها ونهاية الكلمة. إذا أخطأت أعيد كتابة الكلمة بهدوء.\n\nمثال محلول أو نموذج\nجملة أصلية للتدريب: «العمل الجيد يحتاج إلى صبر». أكتبها مرة ببطء، ثم مرة ثانية بصورة أوضح.\n\nأطبق بنفسي\nانسخ جملة التدريب، ثم تحقق من نقط الحروف في «يحتاج» و«الجيد». ضع نقطة في نهاية الجملة.\n\nمفتاح الإجابة النموذجي\nتقبل كتابة مقروءة تحافظ على ترتيب الكلمات والنقاط والفراغات وعلامة النهاية.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["ينسخ جملة واضحة بخط النسخ محافظًا على مواقع الحروف.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"نسخ","meaning":"خط عربي للكتابة الواضحة"},{"word":"سطر","meaning":"مسار أفقي تنتظم عليه الكتابة"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":19,"title":"التعبير: التعبير شفويًا عن الصور؛ كتابة لافتة إعلانية؛ كتابة فقرة مترابطة بتوظيف علامات الترقيم المناسبة","lessonType":"writing","content":"التعبير: التعبير شفويًا عن الصور؛ كتابة لافتة إعلانية؛ كتابة فقرة مترابطة بتوظيف علامات الترقيم المناسبة\n\nما الذي سأتعلمه؟\n• يصف صورة شفهيًا ويكتب لافتة إعلانية قصيرة مفهومة.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nعند وصف صورة أبدأ بما أراه فعلًا ولا أخترع تفاصيل غير ظاهرة. وعند كتابة لافتة أعرض معلومة واحدة أو أكثر بوضوح: اسم المكان، الرسالة، وربما الموعد. أستخدم كلمات مباشرة وعلامات ترقيم مناسبة.\n\nمثال محلول أو نموذج\nمشهد تدريبي متخيل: مكتبة صغيرة أمامها لافتة «معرض الكتاب يوم الجمعة». وصف: «تظهر مكتبة ولوحة تعلن معرضًا للكتب».\n\nأطبق بنفسي\nصف مشهدًا مألوفًا من شارعك بجملتين. اكتب لافتة من سطر واحد لدعوة الجيران إلى حملة نظافة، ثم أضف فقرة من ثلاث جمل.\n\nمفتاح الإجابة النموذجي\nوصف ملتزم بالمشهد، ولافتة تتضمن الدعوة والموعد أو المكان إن وجد، وفقرة مترابطة.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يصف صورة شفهيًا ويكتب لافتة إعلانية قصيرة مفهومة.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"لافتة","meaning":"لوحة تحمل رسالة مختصرة"},{"word":"إعلان","meaning":"رسالة تعرض معلومة للجمهور"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":20,"title":"القراءة: صنع في البحرين","lessonType":"reading","content":"القراءة: صنع في البحرين\n\nما الذي سأتعلمه؟\n• يفهم من نص أصلي معنى الإنتاج المحلي وفائدته.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nنص ضاديوم: «تعمل ورشة في البحرين على صناعة منتجات تستخدمها الأسر يوميًا. يفحص العمال الجودة قبل عرض المنتجات. يختار بعض المشترين السلع المحلية ويدعمون أصحاب الحرف». هذا نص تدريبي مؤلف، وليس نص «صنع في البحرين» المقرر.\n\nمثال محلول أو نموذج\nالمنتج المحلي يُصنع داخل البلد، ويمكن أن يدعم فرص العمل والخبرات المحلية.\n\nأطبق بنفسي\nأين تصنع المنتجات في النص؟ لماذا تُفحص جودتها؟ اذكر مثالًا محليًا تعرفه دون ادعاء تفاصيل لا تعرفها.\n\nمفتاح الإجابة النموذجي\nفي ورشة بالبحرين؛ للتأكد من صلاحيتها وجودتها؛ تُقبل أمثلة حقيقية يعرفها المتعلم.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يفهم من نص أصلي معنى الإنتاج المحلي وفائدته.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"منتج","meaning":"شيء جرى صنعه أو إنتاجه"},{"word":"محلي","meaning":"مرتبط بالبلد نفسه"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":21,"title":"التراكيب اللغوية: أسلوب النفي","lessonType":"grammar","content":"التراكيب اللغوية: أسلوب النفي\n\nما الذي سأتعلمه؟\n• ينفي معنى الجملة بأداة مناسبة دون تغيير المقصود.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nللنفي أدوات متنوعة منها لا، لم، لن، ليس. أراعي الزمن: «لا أتأخر اليوم»؛ «لم أتأخر أمس»؛ «لن أتأخر غدًا». ومع الجملة الاسمية أقول «ليس الجو حارًا». لا أستخدم الأداة عشوائيًا؛ فالزمن يؤثر في الاختيار.\n\nمثال محلول أو نموذج\nأنا أحب التأخير ← «أنا لا أحب التأخير». ذهب أمس ← «لم يذهبْ أمس». سيذهب غدًا ← «لن يذهبَ غدًا».\n\nأطبق بنفسي\nانف «خرج أمس» باستعمال لم. أنف «سيسافر غدًا» باستعمال لن. أكمل «... المكان بعيدًا» بأداة مناسبة.\n\nمفتاح الإجابة النموذجي\nلم يخرجْ أمس؛ لن يسافرَ غدًا؛ «ليس المكان بعيدًا».\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["ينفي معنى الجملة بأداة مناسبة دون تغيير المقصود.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"نفي","meaning":"إنكار وقوع الحدث أو اتصاف الشيء"},{"word":"أداة","meaning":"كلمة تساعد في بناء المعنى"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":22,"title":"الإملاء والخط: كتابة حديث شريف بخط النسخ","lessonType":"spelling","content":"الإملاء والخط: كتابة حديث شريف بخط النسخ\n\nما الذي سأتعلمه؟\n• ينسخ حديثًا نبويًا بعد التثبت من لفظه ومصدره.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nعند كتابة الحديث الشريف يجب التأكد من صحته ولفظه من مصدر معتمد يختاره المعلم. لا نعتمد على أقوال شائعة أو نُنشئ نصًا وننسبه إلى النبي ﷺ. نتدرب على وضوح خط النسخ والتشكيل عند الحاجة، ثم ننقل الحديث الموثق بعناية.\n\nمثال محلول أو نموذج\nتمرين خط غير منسوب إلى الحديث: «الصدق خُلُق حسن». نتعلم رسم الكلمات ثم نراجع الإملاء.\n\nأطبق بنفسي\nمن أين تحصل على النص قبل نسخه؟ لماذا لا يجوز نسب عبارة غير موثقة إلى النبي ﷺ؟ انسخ الجملة التدريبية دون تغيير لفظها.\n\nمفتاح الإجابة النموذجي\nمن مصدر حديثي معتمد يحدد المعلم نصه؛ لأن النسبة تحتاج تثبتًا؛ كتابة «الصدق خُلُق حسن» بوضوح.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["ينسخ حديثًا نبويًا بعد التثبت من لفظه ومصدره.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"حديث","meaning":"قول أو فعل أو تقرير منسوب للنبي ﷺ في علم الحديث"},{"word":"توثيق","meaning":"التحقق من المصدر والصحة"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":23,"title":"التعبير: كتابة حوار بتوظيف أدوات الاستفهام","lessonType":"writing","content":"التعبير: كتابة حوار بتوظيف أدوات الاستفهام\n\nما الذي سأتعلمه؟\n• يكتب حوارًا يستخدم من وأين ومتى وماذا بصورة صحيحة.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nالحوار الناجح يتبادل فيه شخصان السؤال والجواب باحترام. «من» للشخص، «أين» للمكان، «متى» للزمان، و«ماذا» للسؤال عن شيء أو فعل. أبدأ بتحية، ثم أنقل الكلام بالتناوب وأنهي بالشكر.\n\nمثال محلول أو نموذج\nمها: أين اللقاء؟ سلمى: في المكتبة. مها: متى يبدأ؟ سلمى: الساعة الرابعة.\n\nأطبق بنفسي\nأكمل حوارًا من ستة أسطر عن موعد زيارة المكتبة، مستخدمًا ثلاث أدوات استفهام مختلفة وعلامة «؟».\n\nمفتاح الإجابة النموذجي\nتقبل ستة أسطر مرتبة تتضمن التحية، ثلاثة أسئلة مناسبة، إجابات واضحة، وخاتمة مهذبة.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يكتب حوارًا يستخدم من وأين ومتى وماذا بصورة صحيحة.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"تبادل","meaning":"انتقال الكلام بين طرفين"},{"word":"استفهام","meaning":"طلب معرفة معلومة"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":24,"title":"القراءة: في ذاكرتي","lessonType":"reading","content":"القراءة: في ذاكرتي\n\nما الذي سأتعلمه؟\n• يقرأ ذكرى شخصية قصيرة ويحدد زمن الحدث والمشاعر.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nنص ضاديوم الأصلي: «أتذكر أول يوم تعلمت فيه كتابة اسمي. ساعدني المعلم وشعرت بالفرح عندما نجحت. احتفظت بدفتري ذكرى طيبة». النص للتدريب على الفهم، ولا يماثل نص «في ذاكرتي» في الكتاب.\n\nمثال محلول أو نموذج\n«أتذكر» يدل على استرجاع حدث سابق، و«شعرت بالفرح» تعبر عن أثره في النفس.\n\nأطبق بنفسي\nما الحدث الذي يتذكره المتحدث؟ من ساعده؟ ما شعوره؟ اذكر ذكرى تعلم إيجابية خاصة بك.\n\nمفتاح الإجابة النموذجي\nتعلم كتابة اسمه؛ المعلم؛ الفرح؛ تقبل ذكرى شخصية مروية بجملة أو جملتين.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يقرأ ذكرى شخصية قصيرة ويحدد زمن الحدث والمشاعر.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"ذكرى","meaning":"حدث سابق نتذكره"},{"word":"شعور","meaning":"حالة نفسية مثل الفرح أو الحزن"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":25,"title":"التراكيب اللغوية: استعمال الظرف (منذ، مع، بعد)","lessonType":"grammar","content":"التراكيب اللغوية: استعمال الظرف (منذ، مع، بعد)\n\nما الذي سأتعلمه؟\n• يوظف منذ ومع وبعد في جمل صحيحة وفق المعنى.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\n«منذ» ترتبط ببداية زمن امتد إلى وقت الحديث غالبًا، مثل «أعيش هنا منذ عام». «مع» تدل على المصاحبة: «ذهبت مع أخي». «بعد» تدل على الترتيب الزمني أو المكاني بحسب السياق: «رجعت بعد العمل». لا تستعمل الأدوات بالمعنى نفسه.\n\nمثال محلول أو نموذج\nأتعلم العربية منذ شهر. وصلت مع زميلي. قرأت بعد العشاء.\n\nأطبق بنفسي\nأكمل «ذهبت ... صديقي» للمصاحبة. «بدأت العمل ... عامين» للبداية الزمنية. «عدت ... الزيارة» للترتيب.\n\nمفتاح الإجابة النموذجي\nمع؛ منذ؛ بعد.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يوظف منذ ومع وبعد في جمل صحيحة وفق المعنى.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"منذ","meaning":"تعبير عن بداية مدة زمنية"},{"word":"مصاحبة","meaning":"كون الشخص مع غيره"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":26,"title":"الإملاء والخط: مواضع كتابة التاء المفتوحة؛ كتابة جملة بخط النسخ","lessonType":"spelling","content":"الإملاء والخط: مواضع كتابة التاء المفتوحة؛ كتابة جملة بخط النسخ\n\nما الذي سأتعلمه؟\n• يميز مواضع التاء المفتوحة ويكتب جملة مقروءة بخط النسخ.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nتظهر التاء المفتوحة «ت» في آخر بعض الأسماء مثل «بيت» و«بنت»، وفي صيغ فعلية مثل «كتبت». أقرأ الكلمة في سياق ثم أكتبها كاملة من غير إسقاط نقط الحروف المجاورة. أراجع وجود التاء ولا أحولها إلى مربوطة دون قاعدة.\n\nمثال محلول أو نموذج\n«كتبتُ رسالة». «هذا بيت واسع». «البنت تقرأ».\n\nأطبق بنفسي\nحدد التاء المفتوحة في «كتبت» و«بيت». انسخ «كتبتُ رسالة قصيرة» مع مراعاة الفراغات والنقاط.\n\nمفتاح الإجابة النموذجي\nالتاء الأخيرة مفتوحة في كلتا الكلمتين؛ يراجع النص المنسوخ من حيث وضوح الخط ورسم التاء.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يميز مواضع التاء المفتوحة ويكتب جملة مقروءة بخط النسخ.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"تاء مفتوحة","meaning":"تكتب «ت» في آخر الكلمة"},{"word":"خط النسخ","meaning":"خط واضح يستخدم في الكتب والكتابة"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":27,"title":"التعبير: كتابة فقرة مترابطة للمقارنة بين شيئين؛ كتابة فقرة مترابطة لوصف المشاعر","lessonType":"writing","content":"التعبير: كتابة فقرة مترابطة للمقارنة بين شيئين؛ كتابة فقرة مترابطة لوصف المشاعر\n\nما الذي سأتعلمه؟\n• يكتب فقرة مقارنة وأخرى تصف الشعور بألفاظ دقيقة.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nعند المقارنة أحدد وجه شبه واختلاف بين شيئين، مثل المشي وركوب الدراجة. وعند وصف المشاعر أذكر ما شعرت به وسبب الشعور. أتجنب الأحكام المطلقة وأستخدم ألفاظًا دقيقة مثل «أكثر»، «أقل»، «فرِح»، «قلق».\n\nمثال محلول أو نموذج\n«المشي وركوب الدراجة نشاطان مفيدان؛ المشي لا يحتاج إلى دراجة». «شعرت بالفخر حين قرأت أمام المجموعة».\n\nأطبق بنفسي\nاكتب ثلاث جمل تقارن بين وسيلتي تنقل. ثم اكتب ثلاث جمل تصف شعورك بعد تعلم مهارة جديدة وسببه.\n\nمفتاح الإجابة النموذجي\nتقبل مقارنة فيها تشابه واختلاف واضحان ووصف شعور محدد وأسبابه بلغة سليمة.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يكتب فقرة مقارنة وأخرى تصف الشعور بألفاظ دقيقة.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"مقارنة","meaning":"بيان أوجه الشبه والاختلاف"},{"word":"مشاعر","meaning":"أحاسيس الشخص الداخلية"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":28,"title":"القراءة: الأرض الطيبة","lessonType":"reading","content":"القراءة: الأرض الطيبة\n\nما الذي سأتعلمه؟\n• يفهم نصًا تدريبيًا عن الأرض والعمل ويتعرف العلاقة بين السبب والنتيجة.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nنص ضاديوم: «اعتنى المزارع بأرضه. زرع البذور وسقاها في موعد مناسب. نما النبات وأعطى ثمرًا. شكر المزارع كل من ساعده». النص تعليمي أصلي وليس نص «الأرض الطيبة» الرسمي. ألاحظ ترتيب العمل والنتيجة.\n\nمثال محلول أو نموذج\nبذر المزارع البذور وسقاها؛ فساعد ذلك على نمو النبات.\n\nأطبق بنفسي\nماذا فعل المزارع أولًا؟ ما النتيجة بعد رعاية النبات؟ لماذا شكر مساعديه؟ استخرج كلمتين عن الزراعة.\n\nمفتاح الإجابة النموذجي\nزرع البذور؛ نما النبات وأثمر؛ لأنهم تعاونوا معه؛ «بذور» و«نبات» مثالًا.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يفهم نصًا تدريبيًا عن الأرض والعمل ويتعرف العلاقة بين السبب والنتيجة.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"بذور","meaning":"أجزاء يبدأ منها نبات جديد"},{"word":"ثمار","meaning":"نتاج بعض النباتات"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":29,"title":"التراكيب اللغوية: استعمال الفعل الناسخ (أصبح)؛ اشتقاق كلمات مختلفة من نفس الجذر","lessonType":"grammar","content":"التراكيب اللغوية: استعمال الفعل الناسخ (أصبح)؛ اشتقاق كلمات مختلفة من نفس الجذر\n\nما الذي سأتعلمه؟\n• يستعمل أصبح ويشتق كلمات بسيطة من جذر واحد.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nيدخل «أصبح» على الجملة الاسمية فيغيّر إعراب خبرها: «الجو معتدل» تصبح «أصبح الجو معتدلًا». ويدل الفعل في كثير من السياقات على تحول في الحال. أما الاشتقاق فنلاحظ أن كلمات مثل «كتب، كاتب، مكتوب» تشترك في أصل الحروف ك ت ب مع اختلاف المعنى.\n\nمثال محلول أو نموذج\nأصبح المكان نظيفًا. جذر «كتب»: كتب، كتاب، كاتب، مكتوب.\n\nأطبق بنفسي\nحوّل «الشارع نظيف» باستعمال أصبح. اختر كلمة من جذر كتب: «كاتب» أم «سوق»؟ اذكر كلمة مشتقة أخرى من كتب.\n\nمفتاح الإجابة النموذجي\nأصبح الشارع نظيفًا؛ كاتب؛ مثال «مكتبة» أو «مكتوب».\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يستعمل أصبح ويشتق كلمات بسيطة من جذر واحد.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"أصبح","meaning":"فعل ناسخ قد يدل على تحول الحال"},{"word":"جذر","meaning":"حروف أصلية مشتركة بين كلمات مرتبطة"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":30,"title":"الإملاء والخط: كتابة آية بخط النسخ","lessonType":"spelling","content":"الإملاء والخط: كتابة آية بخط النسخ\n\nما الذي سأتعلمه؟\n• ينسخ آية مختارة من مصحف موثق بعد ضبط الكلمات.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nنختار آية محددة من مصحف موثق وبإشراف المعلم. أراجع النص وحركاته قبل النسخ وبعده، وأحافظ على ترتيب الكلمات مع ملاحظة خصوصية الرسم العثماني عند الحاجة. لا أختلق آية للتدريب ولا أغيّر كلمات النص الأصلي.\n\nمثال محلول أو نموذج\nقبل نقل الآية أتمرن بجملة لغوية عادية: «القراءة نور والعلم نافع». أراجع اتصال الحروف ووضوحها.\n\nأطبق بنفسي\nما أول إجراء قبل النسخ؟ اذكر شيئين يجب التحقق منهما في الآية بعد الكتابة. انسخ الجملة التدريبية.\n\nمفتاح الإجابة النموذجي\nالحصول على النص من مصحف معتمد؛ ترتيب الكلمات والحركات ورسم الحروف؛ الجملة المكتوبة بخط واضح.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["ينسخ آية مختارة من مصحف موثق بعد ضبط الكلمات.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"مصحف","meaning":"كتاب يحوي القرآن الكريم"},{"word":"مراجعة","meaning":"مقارنة المكتوب بالمصدر"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":31,"title":"التعبير: التعبير شفويًا عن الصور؛ كتابة فقرة مترابطة بتوظيف علامات الترقيم المناسبة","lessonType":"writing","content":"التعبير: التعبير شفويًا عن الصور؛ كتابة فقرة مترابطة بتوظيف علامات الترقيم المناسبة\n\nما الذي سأتعلمه؟\n• يصف صورة محددة شفهيًا ثم يكتب فقرة مع علامات الترقيم.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nألاحظ في الصورة الأشخاص والأشياء والأفعال الظاهرة فقط، ثم أنظم وصفًا بجملة رئيسة وتفاصيل. يمكن استخدام صورة سوق أو حديقة معروفة، على أن يحدد المعلم الصورة أولًا. أراجع الفواصل والنقاط وعلامة الاستفهام عند وجود سؤال.\n\nمثال محلول أو نموذج\nعن صورة تدريبية مفترضة لحديقة: «في الحديقة أشجار كثيرة. يجلس زوار في الظل، ويلعب أطفال في الساحة».\n\nأطبق بنفسي\nاختر صورة حقيقية تراها. صفها شفهيًا في ثلاث جمل، ثم اكتب فقرة من أربع جمل موضحًا ما تراه مستخدمًا نقطًا وفواصل مناسبة.\n\nمفتاح الإجابة النموذجي\nتقبل فقرة متطابقة مع المشهد المرئي، مترابطة، مع علامات ترقيم مناسبة ودون إضافة تفاصيل غير مرئية.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يصف صورة محددة شفهيًا ثم يكتب فقرة مع علامات الترقيم.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"وصف","meaning":"ذكر صفات ما نراه أو نعرفه"},{"word":"مشهد","meaning":"مجموعة ما يظهر في مكان أو صورة"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1},{"order":32,"title":"مراجعة عامة","lessonType":"assessment","content":"مراجعة عامة\n\nما الذي سأتعلمه؟\n• يراجع مهارات القراءة والقواعد والإملاء والتعبير في المستوى.\n• أوظف المهارة في موقف من حياتي.\n• أراجع إجابتي وأصححها عند الحاجة.\n\nالشرح المبسط\nهذه مراجعة أصلية تجمع المهارات السابقة: الفهم القرائي، فعل الأمر، كان وأصبح، التاء المربوطة والمفتوحة، أدوات النفي، الظرف، كتابة فقرة وحوار وعلامات ترقيم. أبدأ بحل التدريبات وحدي ثم أطالع الإجابات النموذجية للتحقق.\n\nمثال محلول أو نموذج\n«كان الطريق هادئًا. ذهبتُ مع أخي إلى السوق. لم أتأخرْ». لاحظ: كان فعل ناسخ، مع للمصاحبة، ولم لنفي الماضي.\n\nأطبق بنفسي\n1) استعمل فعل أمر في جملة. 2) اختر: «مدرسة» أم «مدرست». 3) أكمل «... أذهب أمس» باستعمال أداة نفي. 4) اكتب ثلاث جمل مترابطة عن مكان زرته.\n\nمفتاح الإجابة النموذجي\n1) مثال «اقرأ الكتاب». 2) «مدرسة». 3) «لم أذهبْ أمس». 4) فقرة صحيحة مترابطة تتضمن بداية وتفصيلًا وخاتمة.\n\nنشاط امتدادي\nأعد صياغة مثال إضافي من عملك أو حياتك اليومية، ثم وضح بصوتك كيف استخدمت قاعدة الدرس أو فكرته بصورة صحيحة.\n\nتنبيه: هذا الشرح والأمثلة والأسئلة محتوى تعليمي أصلي داعم من ضاديوم، يعتمد على عنوان الخطة الرسمية فقط؛ لا ينقل نص الكتاب ولا يثبت مطابقته لفهرس الكتاب. يخضع لمراجعة تربوية.","learning_objectives":["يراجع مهارات القراءة والقواعد والإملاء والتعبير في المستوى.","يوظف المتعلم مهارة الدرس في مثال شخصي.","يتحقق من صحة إجابته باستخدام نموذج أو بإرشاد المعلم."],"vocabulary":[{"word":"مهارة","meaning":"قدرة يتحسن أداؤها بالتدريب"},{"word":"تقويم","meaning":"التحقق من فهم المتعلم وتقدمه"}],"origin":"DADYOOM_ORIGINAL_SUPPORTING_DRAFT","editorialReview":"required","bookTextCopied":false,"semester":1}]$DADYOOM$::jsonb)
),
target as (
 select l.id,p.item
 from public.countries c join public.curricula cur on cur.country_id=c.id
 join public.grades g on g.curriculum_id=cur.id
 join public.units u on u.grade_id=g.id
 join public.lessons l on l.unit_id=u.id
 join payload p on l.lesson_number=(p.item->>'order')::integer AND l.title=(p.item->>'title')
 where c.code='BH' AND cur.name_ar='اللغة العربية — التعليم المستمر'
  AND cur.academic_year='2026-2027'
  AND g.name_ar='الثاني محو الأمية' AND g.grade_number IS NULL
  AND u.semester=1 AND l.semester=1
  AND l.official_content_scope='plan-scheduled'
  AND l.content='محتوى مقرر في الخطة الرسمية الحالية. يُحفظ العنوان كما في المصدر بعد تنظيف أخطاء OCR الشكلية فقط.'
)
update public.lessons l
 set content=t.item->>'content',
 learning_objectives=t.item->'learning_objectives',
 vocabulary=t.item->'vocabulary',
 instructions=coalesce(l.instructions,'[]'::jsonb) || jsonb_build_array(jsonb_build_object(
   'kind','dadyoom_authored_content',
   'origin','DADYOOM_ORIGINAL_SUPPORTING_DRAFT',
   'editorial_review','required',
   'source_publication_ready',false,
   'book_text_copied',false,
   'source_plan','https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf'
 )),
 estimated_minutes=40,
 updated_at=now()
 from target t where l.id=t.id;
